3|const MAX_LOGS = 40;
4|const MAX_OUTPUT_CHARS = 12_000;
5|
6|export type ServerFunctionAiSnapshotInput = {
7|  name: string;
8|  method: string | null;
9|  path: string;
10|  language: string;
11|  engineType: string;
12|  readOnly: boolean;
