22|const clipOutput = (output: Record<string, unknown> | null): Record<string, unknown> | null => {
23|  if (!output) {
24|    return null;
25|  }
26|  try {
27|    const serialized = JSON.stringify(output);
28|    if (serialized.length <= MAX_OUTPUT_CHARS) {
29|      return output;
30|    }
31|    return { truncated: true, preview: serialized.slice(0, MAX_OUTPUT_CHARS) };
32|  } catch {
33|    return { error: 'Unserializable Test Console output' };
34|  }
35|};
36|
37|export const buildServerFunctionAiSnapshot = (input: ServerFunctionAiSnapshotInput): string => (
38|  JSON.stringify({
39|    name: input.name,
40|    method: input.method,
41|    path: input.path,
42|    language: input.language,
43|    engineType: input.engineType,
44|    readOnly: input.readOnly,
45|    testPayload: input.testPayload,
46|    source: input.source,
47|    lastRun: {
48|      isRunning: input.lastRun.isRunning,
49|      output: clipOutput(input.lastRun.output ?? null),
50|      logs: (Array.isArray(input.lastRun.logs) ? input.lastRun.logs : []).slice(-MAX_LOGS).map((log) => ({
51|        time: log.time,
52|        type: log.type,
53|        msg: log.msg,
54|      })),
55|    },
56|  }, null, 2)
57|);
